@page "/inventory"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@attribute [StreamRendering]
@using InventoryApp.Services
@inject IEquipmentService EquipmentService
@inject PersistentComponentState ApplicationState

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_equipment is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _equipment)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<EquipmentItem>? _equipment;
    private PersistingComponentStateSubscription _persistingSubscription;

    protected override async Task OnInitializedAsync()
    {
        _persistingSubscription = ApplicationState.RegisterOnPersisting(PersistEquipment);

        // If persisted state exists (interactive re-init), use it instead of fetching again.
        if (ApplicationState.TryTakeFromJson<List<EquipmentItem>>(
                nameof(_equipment), out var restored))
        {
            _equipment = restored;
        }
        else
        {
            _equipment = await EquipmentService.GetEquipmentAsync();
        }
    }

    private Task PersistEquipment()
    {
        ApplicationState.PersistAsJson(nameof(_equipment), _equipment);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _persistingSubscription.Dispose();
    }
}

